public void changeCompoundingBehaviorByConcurrencyModel()
{
    switch (RetailConfigurationParameters::getDiscountConcurrencyControlModel())
    {
        case RetailDiscountConcurrencyControlModel::CompeteCompoundWithinAcross:
            RadioButtonDiscountCompoundBehavior.selection(RetailDiscountCompoundBehavior::CompoundOnOriginalPrice);
            RetailConfigurationParameters::createOrUpdateDiscountCompoundBehavior(RetailDiscountCompoundBehavior::CompoundOnOriginalPrice);
            RadioButtonDiscountCompoundBehavior.enabled(false);
            break;

        default:
            RadioButtonDiscountCompoundBehavior.enabled(true);
    }
}
